UPDATE `casehistorymbgl` SET `jws`='Huyết áp 117/75mmHg, huyết áp hai tay không chênh lệch rõ, tỉnh táo, tinh thần tốt, nghe phổi hai bên âm thở trong, không nghe ran khô/ran ẩm' WHERE `mbbm`='1757054061199676240' AND `jws`='血压117/75mmHg，双上肢血压无明显差异，神清，精神可，听诊双肺呼吸音清，未闻及干湿性啰音';
UPDATE `casehistorymbgl` SET `xbs`='Bệnh nhân phát hiện huyết áp tăng khi khám sức khỏe 5 năm trước, lúc đó 180/75mmHg, khám tại bệnh viện tỉnh chẩn đoán tăng huyết áp nguyên phát, cao nhất 180/75mmHg, thỉnh thoảng đau đầu, không chóng mặt, hồi hộp, tức ngực hay khó thở.' WHERE `mbbm`='1757054061199676240' AND `xbs`='患者于5年前体检时发现血压升高，当时血压180/75mmHg，就诊于省医院确诊为原发性高血压，血压最高达 180/75mmHg，偶伴头痛，无头晕，无心悸，无胸闷、气短.';
UPDATE `casehistorymbgl` SET `gthjkjy`='1. Ăn nhạt; 2. Kiểm soát năng lượng nạp vào và tăng hoạt động thể lực; 3. Không hút thuốc, hạn chế rượu bia, bệnh nhân tăng huyết áp không nên uống rượu, nếu uống thì ít; 4. Vận động thể thao; 5. Giảm căng thẳng tinh thần, giữ cân bằng tâm lý;' WHERE `mbbm`='1757054061199676240' AND `gthjkjy`='1、低盐膳食；2、控制能量摄入和增加体力活动；3、不吸烟，限制饮酒，不提倡高血压患者饮酒，如饮酒，则应少量；4、体育运动；5、减轻精神压力，保持心理平衡；';
